import{_ as s,o as i,c as t,a0 as e}from"./chunks/framework.Bmhw_dvp.js";const c=JSON.parse('{"title":"网络连接与内网穿透","description":"","frontmatter":{},"headers":[],"relativePath":"guide/network.md","filePath":"guide/network.md","lastUpdated":1787764768000}'),n={name:"guide/network.md"};function l(r,a,h,p,o,d){return i(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="网络连接与内网穿透" tabindex="-1">网络连接与内网穿透 <a class="header-anchor" href="#网络连接与内网穿透" aria-label="Permalink to &quot;网络连接与内网穿透&quot;">​</a></h1><p>ZViewer 部署在内网服务器时，外网用户无法直接访问。取决于你的网络环境，可以从<strong>内网穿透</strong>、<strong>虚拟局域网</strong>、<strong>IPv6 直连</strong>三种方案中选择合适的。</p><h3 id="内网穿透-推荐新手-以樱花为例" tabindex="-1">内网穿透（推荐新手,以樱花为例） <a class="header-anchor" href="#内网穿透-推荐新手-以樱花为例" aria-label="Permalink to &quot;内网穿透（推荐新手,以樱花为例）&quot;">​</a></h3><p><a href="https://www.natfrp.com/" target="_blank" rel="noreferrer">Sakura Frp</a> 是一个免费易用的内网穿透服务，无需自备公网 VPS，注册账号即可使用。</p><h4 id="注册与安装" tabindex="-1">注册与安装 <a class="header-anchor" href="#注册与安装" aria-label="Permalink to &quot;注册与安装&quot;">​</a></h4><ol><li>访问 <a href="https://www.natfrp.com/" target="_blank" rel="noreferrer">Sakura Frp 官网</a> 注册账号。</li><li>在「软件下载」页面下载对应系统的客户端。</li><li>登录后进入「管理面板」→「隧道」→「创建隧道」，配置本地端口为 <code>3333</code>。</li><li>在 ZViewer 的「自定义后端地址」中填入樱花分配的隧道地址，即可在外网使用。</li><li>建议直接在设置中使用域名访问并启用强制HTTPS，以直接实现项目全部功能</li></ol><h3 id="frp-推荐" tabindex="-1">FRP（推荐） <a class="header-anchor" href="#frp-推荐" aria-label="Permalink to &quot;FRP（推荐）&quot;">​</a></h3><p><a href="https://github.com/fatedier/frp" target="_blank" rel="noreferrer">FRP</a> 是一款高性能的反向代理应用，支持 TCP、UDP、HTTP、HTTPS 协议，适合将内网 ZViewer 服务暴露到公网 VPS。</p><h4 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>公网用户 → frps（公网 VPS，端口 3333）→ frpc（内网服务器）→ ZViewer（127.0.0.1:3333）</span></span></code></pre></div><h4 id="服务端配置-公网-vps" tabindex="-1">服务端配置（公网 VPS） <a class="header-anchor" href="#服务端配置-公网-vps" aria-label="Permalink to &quot;服务端配置（公网 VPS）&quot;">​</a></h4><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># frps.toml</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bindPort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 7000                </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># frp 控制端口</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">vhostHTTPPort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 80             </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># HTTP 端口（可选，用于 Let&#39;s Encrypt 验证）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">vhostHTTPSPort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 443           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># HTTPS 端口（可选）</span></span></code></pre></div><h4 id="客户端配置-内网-zviewer-服务器" tabindex="-1">客户端配置（内网 ZViewer 服务器） <a class="header-anchor" href="#客户端配置-内网-zviewer-服务器" aria-label="Permalink to &quot;客户端配置（内网 ZViewer 服务器）&quot;">​</a></h4><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># frpc.toml</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">serverAddr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你的公网VPS_IP&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">serverPort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 7000</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[[proxies]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;zviewer-backend&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tcp&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">localIP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">localPort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 3333</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">remotePort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 3333</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[[proxies]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;zviewer-rtmp&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tcp&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">localIP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">localPort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 3334</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">remotePort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 3334</span></span></code></pre></div><h4 id="访问" tabindex="-1">访问 <a class="header-anchor" href="#访问" aria-label="Permalink to &quot;访问&quot;">​</a></h4><p>配置完成后，外网用户通过 <code>http://公网VPS_IP:3333</code> 访问 ZViewer。</p><blockquote><p>公网 VPS 需开放对应端口（3333、3334）的防火墙/安全组规则。</p></blockquote><h4 id="配置-https-frp-转发" tabindex="-1">配置 HTTPS（FRP 转发） <a class="header-anchor" href="#配置-https-frp-转发" aria-label="Permalink to &quot;配置 HTTPS（FRP 转发）&quot;">​</a></h4><p>如果公网 VPS 有域名，可配置 FRP 的 HTTPS 转发，或使用 Nginx 反代 FRP 端口后申请 Let&#39;s Encrypt 证书。</p><h2 id="虚拟局域网" tabindex="-1">虚拟局域网 <a class="header-anchor" href="#虚拟局域网" aria-label="Permalink to &quot;虚拟局域网&quot;">​</a></h2><h3 id="以-zerotier-为例" tabindex="-1">以 ZeroTier 为例 <a class="header-anchor" href="#以-zerotier-为例" aria-label="Permalink to &quot;以 ZeroTier 为例&quot;">​</a></h3><p><a href="https://www.zerotier.com/" target="_blank" rel="noreferrer">ZeroTier</a> 是一款软件定义网络（SDN）工具，将分布在不同网络的设备组成一个虚拟局域网，设备间可直接通信，无需公网 IP。</p><h4 id="架构-1" tabindex="-1">架构 <a class="header-anchor" href="#架构-1" aria-label="Permalink to &quot;架构&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>外网用户（安装 ZeroTier）←→ ZeroTier 虚拟网络 ←→ 内网 ZViewer 服务器（安装 ZeroTier）</span></span></code></pre></div><h4 id="注册与创建网络" tabindex="-1">注册与创建网络 <a class="header-anchor" href="#注册与创建网络" aria-label="Permalink to &quot;注册与创建网络&quot;">​</a></h4><ol><li>访问 <a href="https://my.zerotier.com/" target="_blank" rel="noreferrer">ZeroTier Central</a> 注册账号。</li><li>点击 <strong>Create A Network</strong> 创建一个网络。</li><li>记下生成的 <strong>Network ID</strong>（如 <code>8056c2e21c000001</code>）。</li></ol><h4 id="安装-zerotier" tabindex="-1">安装 ZeroTier <a class="header-anchor" href="#安装-zerotier" aria-label="Permalink to &quot;安装 ZeroTier&quot;">​</a></h4><p><strong>Linux（内网服务器）</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://install.zerotier.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zerotier-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> join</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zerotier-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> allowManaged=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><p><strong>Windows/macOS（外网用户）</strong>：</p><ol><li>从 <a href="https://www.zerotier.com/download/" target="_blank" rel="noreferrer">ZeroTier 官网</a> 下载客户端安装。</li><li>点击系统托盘图标 → <strong>Join Network</strong> → 输入 Network ID。</li><li>勾选 <strong>Allow Managed IP</strong>。</li></ol><h4 id="授权设备" tabindex="-1">授权设备 <a class="header-anchor" href="#授权设备" aria-label="Permalink to &quot;授权设备&quot;">​</a></h4><p>在 <a href="https://my.zerotier.com/" target="_blank" rel="noreferrer">ZeroTier Central</a> 的网络管理页面中，勾选已连接设备旁边的复选框以授权入网。</p><h4 id="访问-1" tabindex="-1">访问 <a class="header-anchor" href="#访问-1" aria-label="Permalink to &quot;访问&quot;">​</a></h4><p>授权后，ZeroTier 会为每台设备分配一个虚拟 IP（如 <code>10.147.20.1</code>）。外网用户通过该 IP 访问内网 ZViewer 服务：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://10.147.20.1:3333</span></span></code></pre></div><blockquote><p>ZeroTier 的免费版支持最多 25 台设备，适合团队使用。设备间通信为 P2P 直连，不经过中心服务器，速度取决于两端带宽。</p></blockquote><h2 id="方案对比" tabindex="-1">方案对比 <a class="header-anchor" href="#方案对比" aria-label="Permalink to &quot;方案对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>是否需要公网 VPS</th><th>速度</th><th>配置难度</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>FRP</strong></td><td>是（需一台公网 VPS）</td><td>受 VPS 带宽限制，中转流量</td><td>中等</td><td>有公网 VPS 且需要稳定服务的场景</td></tr><tr><td><strong>Sakura Frp</strong></td><td>否（使用服务商节点）</td><td>受免费节点带宽限制</td><td>简单</td><td>快速测试、临时分享、无公网 VPS 的场景</td></tr><tr><td><strong>ZeroTier</strong></td><td>否（P2P 直连）</td><td>取决于两端带宽，直连最快</td><td>简单</td><td>多设备组网、长期使用、需要高速传输的场景</td></tr><tr><td><strong>IPv6 直连</strong></td><td>否</td><td>不限速（直连）</td><td>简单</td><td>服务器与客户端均有可达 IPv6 的场景</td></tr></tbody></table><h3 id="选择建议" tabindex="-1">选择建议 <a class="header-anchor" href="#选择建议" aria-label="Permalink to &quot;选择建议&quot;">​</a></h3><ul><li><strong>已有公网 VPS</strong> → 使用 FRP，稳定可控。</li><li><strong>无公网 VPS，偶尔外网访问</strong> → 使用 Sakura Frp，免费快速。</li><li><strong>需要长期稳定高速访问，且设备较多</strong> → 使用 ZeroTier，P2P 直连不限速。</li><li><strong>服务器与客户端都有可达 IPv6</strong> → 直接 IPv6 直连，无需任何穿透。</li></ul><h2 id="ipv6-连接" tabindex="-1">IPv6 连接 <a class="header-anchor" href="#ipv6-连接" aria-label="Permalink to &quot;IPv6 连接&quot;">​</a></h2><p>如果服务器和客户端都拥有<strong>公网（可路由）的 IPv6 地址</strong>，可以直接通过 IPv6 直连，无需内网穿透。ZViewer 后端<strong>默认同时监听 IPv4 与 IPv6（双栈）</strong>，因此服务器获得公网 IPv6 后，客户端即可直接访问。</p><h3 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h3><ul><li>服务器分配到可路由的公网 IPv6 地址，且防火墙放行 <code>3333</code>、<code>3334</code> 端口。</li><li>客户端所在网络能访问 IPv6（大多数现代宽带与蜂窝网络已支持双栈）。</li></ul><h3 id="访问方式" tabindex="-1">访问方式 <a class="header-anchor" href="#访问方式" aria-label="Permalink to &quot;访问方式&quot;">​</a></h3><p>外网用户通过服务器的公网 IPv6 地址访问（IPv6 地址需用方括号包裹）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://[公网IPv6地址]:3333</span></span></code></pre></div><h3 id="获取公网-ipv6-地址" tabindex="-1">获取公网 IPv6 地址 <a class="header-anchor" href="#获取公网-ipv6-地址" aria-label="Permalink to &quot;获取公网 IPv6 地址&quot;">​</a></h3><ul><li><strong>家庭宽带</strong>：在光猫/路由器上开启 IPv6（如 PPPoE Dial-Out），为内网设备分配公网 IPv6，并放行 <code>3333</code>、<code>3334</code> 端口。</li><li><strong>VPS</strong>：通常在控制台或运营商侧直接分配公网 IPv6。</li></ul><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>家庭宽带 IPv6 前缀通常随拨号变化，如需稳定访问，可结合 <strong>IPv6 DDNS</strong> 将动态地址解析到域名。</li><li>用 IPv6 访问时若配置了 SSL 证书，证书的 SAN 需包含该 IPv6 地址（<code>localhost</code> 自签证书的 SAN 含 <code>::1</code>；Let&#39;s Encrypt 签发支持公网 IP，含 IPv6）。详见 <a href="/dev/https">开发 - HTTPS 与证书</a>。</li><li>若客户端仅为 IPv4，无法直接访问 IPv6，仍需内网穿透或虚拟局域网方案。</li></ul>`,52)])])}const g=s(n,[["render",l]]);export{c as __pageData,g as default};
